INSERT INTO Projects (ProjectID, ProjectName, StartDate, EndDate, Budget)
VALUES (101, 'Quantum Computing Initiative', '2023-01-15', '2025-12-31', 1500000.00);

INSERT INTO Researchers (ResearcherID, FirstName, LastName, Department)
VALUES (201, 'Alice', 'Smith', 'Physics');

INSERT INTO ProjectResearchers (ProjectID, ResearcherID, Role)
VALUES (101, 201, 'Lead Researcher');

SELECT ProjectName, StartDate, EndDate, Budget
FROM Projects
WHERE CURDATE() BETWEEN StartDate AND EndDate
AND Budget > 100000.00;

SELECT R.Department, SUM(P.Budget) AS TotalDepartmentBudget
FROM Projects AS P
JOIN ProjectResearchers AS PR ON P.ProjectID = PR.ProjectID
JOIN Researchers AS R ON PR.ResearcherID = R.ResearcherID
GROUP BY R.Department;

SELECT FirstName, LastName, COUNT(PR.ProjectID) AS NumberOfProjects
FROM Researchers AS R
JOIN ProjectResearchers AS PR ON R.ResearcherID = PR.ResearcherID
GROUP BY R.ResearcherID, FirstName, LastName
HAVING COUNT(PR.ProjectID) > 2;

UPDATE Projects
SET EndDate = '2026-06-30', Budget = 1750000.00
WHERE ProjectID = 101;

